/**
 * Number of months to exclude participants who have previously participated in a study.
 * Used only when `hasNeverParticipated` is false. For example, `months: 3` excludes participants who participated in the past 3 months.
 */
export type PastParticipationMonths = '-1' | '1' | '2' | '3' | '6' | '9' | '12';

export type UpsertPastParticipationDto = {
    /**
     * If true &rarr; only include participants who have never participated in a project with the researcher.
     * If false &rarr; only include participants who have not participated in a project with the researcher in the past `months` months.
     */
    hasNeverParticipated?: boolean;
    months?: PastParticipationMonths;
    /**
     * It's autocalculated based on the `hasNeverParticipated` / `months` entered and displays in the API response
     *
     * @deprecated
     */
    since?: string;
};

export type LocationCoordinate = {
    longitude: number;
    latitude: number;
};

export type CreateLocationDto = {
    googleId?: string;
    region?: string;
    city: string;
    state?: string;
    country: CountryCode;
    zipcode?: string;
    location: LocationCoordinate;
};

export type CreateProjectCitiesDto = {
    location: CreateLocationDto;
};

export type NdaType = 'none' | 'file' | 'link';

export type NdaDetailsDto = {
    ndaType?: NdaType;
    ndaLink?: string | null;
};

export type ExternalResearcher = {
    /**
     * A unique researcher ID provided by you, used to associate and filter projects.
     */
    researcherId: string;
    /**
     * Display name used when messaging participants. Full name is not required — participants only ever see the first token.
     */
    researcherName?: string;
    /**
     * Optional additional filtering. This researcher's internal teamId from your organization.
     */
    teamId?: string;
    companyName?: string;
    /**
     * Optional additional filtering. This researcher's internal companyId from your organization.
     */
    companyId?: string;
    /**
     * Link to book a meeting with the researcher. Required if targetResearchMethodology of project is oneOnOne or focusGroup.
     */
    bookingUrl?: string;
};

/**
 * Create B2B Project
 */
export type CreateB2bProjectDto = {
    /**
     * Project Title.
     * This is visible to Respondents, do not mention any incentive amount as you may change it during your project.
     */
    publicTitle: string;
    /**
     * Internal Project Name.
     * This is visible only to your organization.
     * Character Limit: Min 3 and Max 50.
     */
    publicInternalName: string;
    /**
     * Required when publishing a project.
     * This is visible to Respondents.
     * A short description of the project visible to participants. This should clearly outline the purpose, requirements, and expectations for participation.
     * Character Limit: Max 800.
     */
    publicDescription?: string;
    targetMarketType: B2bAudienceTypes;
    typeOfResearch: ResearchTypes;
    targetResearchMethodology: KindOfResearch;
    /**
     * For Unmoderated Studies and Surveys only.
     */
    unmoderatedStudyOrSurvey?: UnmoderatedStudyOrSurvey;
    participantTimeRequiredMinutes: number;
    /**
     * Dollars ranging: Min 5 and Max 1000.
     * Pro tip: Set your incentive at or above $2 per minute (B2C) or $3 per minute (B2B) to attract quality participants faster.
     * More tips to pick the right incentive: https://help.respondent.io/en/articles/5471087-what-is-the-best-incentive-for-my-research-project
     */
    incentiveAmount: number;
    /**
     * Number of Participants
     * We will recruit up to 3 times your target number of qualified participants.
     * Number Limit: Min 1 and Max 500.
     */
    targetNumberOfParticipants: number;
    targetCountry?: ProjectCountryCode;
    targetCountries?: Array<ProjectCountryCode>;
    /**
     * External-screener organizations only. The URL of your own screener:
     * participants who qualify on the Respondent screener are sent here to
     * complete yours, with `respondent_*` correlation parameters appended
     * (`respondent_user_id`, `respondent_profile_id`,
     * `respondent_screener_response_id`, `respondent_project_id`). Post their
     * answers back with the External Screener Answers endpoint **before**
     * redirecting them to the apply page they came from — never to the
     * project's `completionUrl`. Pairs with `externalQuestions`: a project may
     * hold just the link while it is a draft (declare the catalog later through
     * the external-screener-questions bulk endpoint), but publishing requires
     * the two together.
     */
    externalScreenerLink?: string | null;
    /**
     * External-screener organizations only. The declared catalog of your
     * screener's questions: answer rows are validated against these
     * `questionId`s, and the application reads as submitted once every declared
     * question has an answer (or an answers payload says `complete: true`).
     * Also settable via the external-screener-questions bulk endpoint. Pairs
     * with `externalScreenerLink`: publishing requires the two together.
     */
    externalQuestions?: Array<ExternalQuestion>;
    targetJobFunctions?: Array<JobFunction>;
    /**
     * Required for In-Person projects only.
     * Please provide the full address (including city & state if applicable) where the project will be conducted.
     */
    targetLocationRespondentInPerson?: ProjectLocationInPerson;
    targetHouseholdIncome?: Array<HouseholdIncome>;
    targetGenders?: Gender;
    targetEducation?: Array<EducationLevel>;
    targetEthnicities?: Array<Ethnicities>;
    targetAgeGroups?: Array<AgeGroup>;
    ndaType?: NdaTypeDeprecated;
    /**
     * Use ndaDetails.ndaLink.
     *
     * @deprecated
     */
    ndaLink?: string | null;
    seniority?: Array<SeniorityLevel>;
    /**
     * - Autopay is used to automatically pay participants after they complete a project.
     * - If not provided, defaults to `true`.
     * - Autoinvite is used to automatically invite participants to a project if they qualify after completing the screener.
     * - Only available when `targetResearchMethodology` is one of: [`unmoderatedStudy`, `survey`].
     * - If not provided, defaults to `false`.
     */
    automations?: Automation;
    keyQualifiers?: Array<KeyQualifierB2b>;
    /**
     * Flat advanced-targeting attribute map (relationship status, languages,
     * devices, products & services, professional and shopping preferences, …).
     * Each provided attribute acts as a soft preference unless promoted to a hard
     * filter via `keyQualifiers`, EXCEPT for the always-hard attributes that act
     * as hard filters whenever set and cannot be soft-moded (they are absent from
     * the `KeyQualifier` enum): `areaType`, `workSetting`, `browsers`,
     * `computerOS`, `programmingLanguages`, `tabletOS`, `smartphoneOS`, `webcam`,
     * `mobilePhoneWithInternet`, `headsetWithMicrophone`.
     * All advanced attributes are available identically on B2C and B2B payloads.
     * On update, advancedTargeting is merged per attribute: include a key to set
     * it, send `null` to clear it, omit a key to leave it unchanged. For array
     * attributes an empty array `[]` also clears the targeting (treated as no
     * target). `keyQualifiers` is replaced as a whole.
     * **Beta:** behind the `advanced-targeting-attributes` org feature flag.
     */
    advancedTargeting?: AdvancedTargeting;
    /**
     * - If researcher wants to filter out participants who have participated in past projects.
     * - Past Participation logic is used at Researcher level based on external reseacher id.
     * - The participant must have been paid for a project to count as a past participant.
     * - Past participation filtering is available within 4 hours of a payout being made, NOT immediately after payment.
     */
    filterPastParticipation?: UpsertPastParticipationDto;
    targetCompanySize?: Array<CompanySize>;
    targetCities?: Array<CreateProjectCitiesDto>;
    /**
     * ndaType = file is not supported on this endpoint. Use the [Upload NDA File endpoint](https://developers.respondent.io/reference/projectscontroller_uploadfilesformdata) to upload NDA documents
     */
    ndaDetails?: NdaDetailsDto;
    /**
     * Required for all projects to identify your researcher with Respondent to differentiate from other researchers recruiting through your platform.
     */
    externalResearcher: ExternalResearcher;
    /**
     * Pass ids only.
     * IDs differ from staging to production.
     * Required for Industry professionals (B2B) projects.
     * Array: Min 1.
     */
    targetProfessionalIndustries: Array<string>;
    /**
     * Pass ids only.
     * IDs differ from staging to production.
     * Array: Max 10.
     */
    targetJobTitles?: Array<string>;
    /**
     * Pass ids only.
     * IDs differ from staging to production.
     * Array: Min 0 and Max: 25.
     * Select skills, knowledge areas, tools and/or certifications you would like to target.
     */
    targetAudienceSkills?: Array<string>;
};

/**
 * Audience type to be targeted for this project. Example values: Industry professionals (B2B) or General Population (B2C)
 */
export type B2cAudienceTypes = 'b2c';

/**
 * You can select audience signals to restrict who qualifies for this project. Learn more about filters vs signals.
 * Learn more about filters vs signals: https://help.respondent.io/en/articles/5482285-filtering-targeting-and-qualifying
 */
export type KeyQualifierB2c = 'targetProjectTopics' | 'relationshipStatus' | 'languages' | 'numberOfChildren' | 'numberOfChildrenLiveAtHome' | 'childrenBirthYears' | 'livingSituation' | 'pets' | 'homeOwner' | 'nationality' | 'militaryServiceStatus' | 'employmentStatuses' | 'cloudPlatforms' | 'codingAITools' | 'designPrototypingTools' | 'productivitySoftware' | 'streamingServices' | 'foodDeliveryServices' | 'onlineBankingTools' | 'onlineLearningPlatforms' | 'onlineMarketplacePlatforms' | 'onlineTravelBooking' | 'smartHomeDevices' | 'socialNetworkPlatforms' | 'vehicleBrands' | 'healthWellnessApps' | 'onlineShoppingFrequency';

