    publicDescription?: string;
    organizationId?: string;
    teamId?: string;
    projectStatus: ProjectStatus;
    projectRecruitingStatus: ProjectRecruitingStatus;
    targetMarketType: AudienceTypes;
    typeOfResearch: ResearchTypes;
    targetResearchMethodology: KindOfResearch;
    /**
     * For Unmoderated Studies and Surveys only.
     */
    unmoderatedStudyOrSurvey?: UnmoderatedStudyOrSurvey;
    /**
     * External-screener organizations only. The URL of your own screener:
     * participants who qualify on the Respondent screener are sent here to
     * complete yours, with `respondent_*` correlation parameters appended
     * (`respondent_user_id`, `respondent_profile_id`,
     * `respondent_screener_response_id`, `respondent_project_id`). Post their
     * answers back with the External Screener Answers endpoint **before**
     * redirecting them to the apply page they came from — never to the
     * project's `completionUrl`. Pairs with `externalQuestions`: a project may
     * hold just the link while it is a draft (declare the catalog later through
     * the external-screener-questions bulk endpoint), but publishing requires
     * the two together.
     */
    externalScreenerLink?: string | null;
    /**
     * External-screener organizations only. The declared catalog of your
     * screener's questions: answer rows are validated against these
     * `questionId`s, and the application reads as submitted once every declared
     * question has an answer (or an answers payload says `complete: true`).
     * Also settable via the external-screener-questions bulk endpoint. Pairs
     * with `externalScreenerLink`: publishing requires the two together.
     */
    externalQuestions?: Array<ExternalQuestion>;
    participantTimeRequiredMinutes: number;
    /**
     * Dollars ranging: Min 5 and Max 1000.
     * Pro tip: Set your incentive at or above $2 per minute (B2C) or $3 per minute (B2B) to attract quality participants faster.
     * More tips to pick the right incentive: https://help.respondent.io/en/articles/5471087-what-is-the-best-incentive-for-my-research-project
     */
    incentiveAmount: number;
    /**
     * Number of Participants
     * We will recruit up to 3 times your target number of qualified participants.
     * Number Limit: Min 1 and Max 500.
     */
